from PyQt5.uic import loadUi
from PyQt5.QtWidgets import QApplication, QMessageBox


def verif_base(ch,dom):
    i=0
    while i<len(ch) and dom.find(ch[i])!=-1 :
        i+=1
    return i==len(ch)
        
    


def verif_entree(bd,entree):
    if bd=="2" and not verif_base(entree,"01"):
        QMessageBox.critical(win,"erreur","nombre binaire non valide")
        return False
    if bd=="8" and not verif_base(entree,"01234567"):
        QMessageBox.critical(win,"erreur","nombre octale  non valide")
        return False
    if bd=="10" and not verif_base(entree,"0123456789"):
        QMessageBox.critical(win,"erreur","nombre decimale  non valide")
        return False
    if bd=="16" and not verif_base(entree,"0123456789ABCDEF"):
        QMessageBox.critical(win,"erreur","nombre hexadecimale non valide")
        return False
    return True
        
  
  
def conversion():
    bd=win.bd.currentText()
    bf=win.bf.currentText()
    entree=win.entree.text()
    if bd=="choisir une base" or bf=="choisir une base" :
        QMessageBox.critical(win,"erreur","base depart ou base final invalide")
    elif bd==bf :
        QMessageBox.critical(win,"erreur","base depart egale a la  base final ")
    elif entree=="" or   verif_entree(bd,entree)==False:
         QMessageBox.critical(win,"erreur","entree invalide ")
         

app = QApplication([])
win = loadUi("interface_conversion.ui")
win.show()
win.btn1.clicked.connect(conversion)
app.exec_()

